11: /** Allowed path prefixes or exact paths for lite clients. */
12: function isPathAllowed(pathname: string, method: string): boolean {
13:   const m = (method || "GET").toUpperCase();
14:   // Wave 3: worker task detail + own-report read — RBAC enforced in route handlers; lite middleware only gates surface area.
15:   if (m === "GET" && /^\/api\/v1\/tasks\/[^/]+$/.test(pathname)) return true;
16:   // Task chat (Worker ↔ Manager): list/create/soft-delete — RBAC in handlers.
17:   if (/^\/api\/v1\/tasks\/[^/]+\/messages(\/[^/]+)?$/.test(pathname)) {
18:     if (m === "GET" || m === "POST" || m === "DELETE") return true;
19:   }
20:   if (m === "GET" && /^\/api\/v1\/reports\/[^/]+$/.test(pathname)) return true;
21:   // Worker/iOS+Android lite apps list tenant projects (tenant-scoped; same as dashboard read).
22:   if (pathname === "/api/v1/projects" && method === "GET") return true;
23:   if (pathname === "/api/v1/config") return true;
24:   if (pathname.startsWith("/api/v1/worker")) return true;
25:   if (pathname.startsWith("/api/v1/sync")) return true;
26:   if (pathname.startsWith("/api/v1/media/upload-sessions")) return true;
27:   if (pathname.startsWith("/api/v1/devices")) return true;
28:   if (pathname.startsWith("/api/v1/auth")) return true;
29:   if (/^\/api\/v1\/reports\/[^/]+\/analysis-status$/.test(pathname)) return true;
30:   // Worker home intelligence: checklist + localized hints (same routes as web; lite still needs allow-list entry).
31:   if (pathname === "/api/v1/activation/status" && m === "GET") return true;
32:   if (pathname === "/api/v1/help/hints" && m === "POST") return true;
33:   if (pathname === "/api/v1/help/assistant" && m === "POST") return true;
34:   if (pathname === "/api/v1/help/assistant/events" && m === "POST") return true;
35:   // Inbox is user-scoped in the handler (manager_notifications.user_id = caller).
36:   if (pathname === "/api/v1/notifications" && m === "GET") return true;
37:   if (pathname === "/api/v1/notifications/unread-count" && m === "GET") return true;
38:   if (pathname === "/api/v1/notifications/read-all" && (m === "PATCH" || m === "POST")) return true;
39:   if (m === "PATCH" && /^\/api\/v1\/notifications\/[^/]+\/read$/.test(pathname)) return true;
40:   if (m === "POST" && /^\/api\/v1\/notifications\/[^/]+\/opened$/.test(pathname)) return true;
41:   return false;
42: }
